  const baggybottoms = filteredProducts.bottoms.filter(product =>
    productMatchesKeywords(product, ['baggy', 'loose', 'relaxed'])
  )

  const trendyBottoms = [...wideLegBottoms, ...baggyBottoms]
  if (trendyBottoms.length > 0) {
