  // Elegant style
  if (
    text.includes('elegant') ||
    text.includes('refined') ||
    text.includes('polished') ||
    text.includes('chic')
  ) {
    tags.add('elegant')
  }

  // Edgy style
  if (
    text.includes('edgy') ||
    text.includes('bold') ||
    text.includes('daring') ||
    text.includes('statement')
  ) {
    tags.add('edgy')
  }

  // Preppy style
  if (
    text.includes('preppy') ||
    text.includes('collegiate') ||
    text.includes('ivy') ||
    text.includes('polo')
  ) {
    tags.add('preppy')
  }

  // Pinterest 2026 Aesthetics

  // Clean girl aesthetic
  if (
    text.includes('minimal') ||
    text.includes('neutral') ||
    text.includes('soft') ||
    text.includes('fresh') ||
    (text.includes('light') && text.includes('tone'))
  ) {
    tags.add('clean-girl')
  }

  // Scandinavian minimal aesthetic
  if (
    text.includes('scandinavian') ||
    (text.includes('simple') && text.includes('clean')) ||
    (text.includes('neutral') && text.includes('palette')) ||
    text.includes('quality basics')
  ) {
    tags.add('scandinavian-minimal')
  }

  // Street style aesthetic
  if (
    text.includes('oversized') ||
    text.includes('baggy') ||
    text.includes('urban') ||
    text.includes('layered') ||
    text.includes('chunky') ||
    text.includes('street')
  ) {
    tags.add('street-style')
  }

  // Corporate chic aesthetic
  if (
    text.includes('structured') ||
    text.includes('tailored') ||
    (text.includes('wide-leg') || text.includes('wide leg')) ||
    text.includes('blazer') ||
    (text.includes('professional') && text.includes('chic'))
  ) {
    tags.add('corporate-chic')
  }

  // Quiet luxury aesthetic
  if (
    text.includes('understated') ||
    text.includes('premium') ||
    text.includes('timeless') ||
    (text.includes('refined') && !text.includes('edgy')) ||
    text.includes('cashmere') ||
    text.includes('quiet luxury')
  ) {
    tags.add('quiet-luxury')
  }

  // Y2K revival aesthetic
  if (
    text.includes('low-rise') ||
    text.includes('colorful') ||
    text.includes('playful') ||
    text.includes('platform') ||
    text.includes('retro') ||
    text.includes('y2k')
  ) {
    tags.add('y2k-revival')
  }

  // Default to classic if no tags found
  if (tags.size === 0) {
    tags.add('classic')
  }

  return Array.from(tags).slice(0, 3) // Limit to 3 most relevant
}

/**
 * Detect pattern from product name
 */
export function detectPattern(name: string): PatternType | undefined {
  const lower = name.toLowerCase()

  if (lower.includes('stripe') || lower.includes('ลายริ้ว')) return 'striped'
  if (lower.includes('floral') || lower.includes('ดอกไม้')) return 'floral'
  if (lower.includes('plaid') || lower.includes('ตาราง')) return 'plaid'
  if (lower.includes('checkered') || lower.includes('checker')) return 'checkered'
  if (lower.includes('polka') || lower.includes('dot')) return 'polka-dot'
  if (lower.includes('geometric')) return 'geometric'
  if (lower.includes('abstract')) return 'abstract'
  if (lower.includes('animal') || lower.includes('leopard') || lower.includes('zebra')) return 'animal-print'
  if (lower.includes('print')) return 'print'

  return 'solid' // Default
}

/**
 * Detect material from product name or description
 */
export function detectMaterial(text: string): MaterialType | undefined {
  const lower = text.toLowerCase()

  if (lower.includes('cotton') || lower.includes('คอตตอน')) return 'cotton'
  if (lower.includes('polyester')) return 'polyester'
  if (lower.includes('linen') || lower.includes('ลินิน')) return 'linen'
  if (lower.includes('silk') || lower.includes('ไหม')) return 'silk'
  if (lower.includes('wool') || lower.includes('woolen')) return 'wool'
  if (lower.includes('denim') || lower.includes('เดนิม') || lower.includes('jean')) return 'denim'
  if (lower.includes('leather') || lower.includes('หนัง')) return 'leather'
  if (lower.includes('synthetic')) return 'synthetic'

  return 'blend' // Default
}

/**
 * Comprehensive style analysis
 */
export interface StyleAnalysis {
  tags: StyleTag[]
  pattern?: PatternType
  material?: MaterialType
  vibe: string
}

/**
 * Analyze overall style of a product
 */
export function analyzeProductStyle(name: string, description?: string): StyleAnalysis {
  const tags = assignStyleTags(name, description)
  const pattern = detectPattern(name)
  const material = detectMaterial(`${name} ${description || ''}`)

  // Determine overall vibe
  let vibe = 'neutral'
  if (tags.includes('elegant') || tags.includes('formal')) vibe = 'sophisticated'
  else if (tags.includes('casual') || tags.includes('minimalist')) vibe = 'relaxed'
  else if (tags.includes('trendy') || tags.includes('edgy')) vibe = 'bold'
  else if (tags.includes('classic')) vibe = 'timeless'

  return {
    tags,
    pattern,
    material,
    vibe,
  }
}

/**
 * Outfit Generator
 *
 * Generates fashion outfit recommendations from product catalog
 */

import type { Product, Outfit } from './types'

/**
 * Product category types for outfit composition
 */
export type ProductCategory = 'tops' | 'bottoms' | 'shoes' | 'dresses' | 'accessories' | 'other'

export interface CategorizedProducts {
  tops: Product[]
  bottoms: Product[]
  shoes: Product[]
  dresses: Product[]
  accessories: Product[]
  other: Product[]
}

/**
 * Outfit style templates
 */
export type OutfitStyle = 'business' | 'casual' | 'formal' | 'weekend' | 'date' | 'workout' | 'any'

/**
 * Categorize a product based on its name and sub-category
 */
export function categorizeProduct(product: Product): ProductCategory {
  const name = product.name.toLowerCase()
  const subCategory = (product as any).subCategory?.toLowerCase() || ''
  const combined = `${name} ${subCategory}`

  // Dresses (standalone outfit items for women)
  if (combined.includes('dress') || combined.includes('กระโปรง')) {
    return 'dresses'
  }

  // Tops (shirts, blouses, t-shirts, tops, blazers, jackets)
  if (
    combined.includes('shirt') ||
    combined.includes('blouse') ||
    combined.includes('t-shirt') ||
    combined.includes('tee') ||
    combined.includes('top') ||
    combined.includes('blazer') ||
    combined.includes('jacket') ||
    combined.includes('coat') ||
    combined.includes('sweater') ||
    combined.includes('hoodie') ||
    combined.includes('เสื้อ')
  ) {
    return 'tops'
  }

  // Bottoms (pants, trousers, jeans, shorts, skirts)
  if (
    combined.includes('pants') ||
    combined.includes('trousers') ||
    combined.includes('jeans') ||
    combined.includes('shorts') ||
    combined.includes('skirt') ||
    combined.includes('กางเกง')
  ) {
    return 'bottoms'
  }

  // Shoes (shoes, boots, sneakers, sandals)
  if (
    combined.includes('shoe') ||
    combined.includes('boot') ||
    combined.includes('sneaker') ||
    combined.includes('sandal') ||
    combined.includes('loafer') ||
    combined.includes('heel') ||
    combined.includes('รองเท้า')
  ) {
    return 'shoes'
  }

  // Accessories (bags, belts, watches, sunglasses, jewelry)
  if (
    combined.includes('bag') ||
    combined.includes('belt') ||
    combined.includes('watch') ||
    combined.includes('sunglass') ||
    combined.includes('jewelry') ||
    combined.includes('necklace') ||
    combined.includes('bracelet') ||
    combined.includes('ring') ||
    combined.includes('earring') ||
    combined.includes('scarf') ||
    combined.includes('hat') ||
    combined.includes('กระเป๋า') ||
    combined.includes('เข็มขัด')
  ) {
    return 'accessories'
  }

  return 'other'
}

/**
 * Categorize a list of products into categories
 */
export function categorizeProducts(products: Product[]): CategorizedProducts {
  const categorized: CategorizedProducts = {
    tops: [],
    bottoms: [],
    shoes: [],
    dresses: [],
    accessories: [],
    other: [],
  }

  for (const product of products) {
    const category = categorizeProduct(product)
    categorized[category].push(product)
  }

  return categorized
}

/**
 * Get random item from array
 */
function randomPick<T>(items: T[]): T | undefined {
  if (items.length === 0) return undefined
  return items[Math.floor(Math.random() * items.length)]
}

/**
 * Get multiple random items from array
 */
function randomPickMultiple<T>(items: T[], count: number): T[] {
  if (items.length === 0) return []
  const shuffled = [...items].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, Math.min(count, items.length))
}

/**
 * Generate outfit title based on products
 */
function generateOutfitTitle(items: Product[], style: OutfitStyle): string {
  // Try to create product-based titles
  if (items.length > 0) {
    const brands = [...new Set(items.map(p => p.brand).filter(Boolean))]
    const categories: string[] = []

    items.forEach(item => {
      const category = categorizeProduct(item)
      if (category === 'tops') categories.push('Top')
      if (category === 'bottoms') categories.push('Bottoms')
      if (category === 'dresses') categories.push('Dress')
      if (category === 'shoes') categories.push('Shoes')
    })

    // If we have a recognizable brand, use it
    if (brands.length > 0 && brands[0]) {
      const mainBrand = brands[0]
      if (categories.length > 0) {
        return `${mainBrand} ${categories.slice(0, 2).join(' & ')}`
      }
      return `${mainBrand} Outfit`
    }

    // Otherwise use category combinations
    if (categories.length >= 2) {
      return `${categories[0]} & ${categories[1]} Ensemble`
    }
  }

  // Fallback to style-based titles
  const styleLabels: Record<OutfitStyle, string[]> = {
    business: ['ลุคทำงานมืออาชีพ', 'สไตล์ผู้บริหาร', 'ชุดทำงานพร้อมลุย', 'ลุคสาวออฟฟิศสุดชิค'],
    casual: ['ลุควันสบายๆ', 'สไตล์ชิลๆ', 'ชุดใส่เล่นดูดี', 'แคชชวลสไตล์'],
    formal: ['ลุคออกงานหรู', 'ชุดทางการ', 'สไตล์เรียบหรู', 'สวยสง่าออกงาน'],
    weekend: ['ลุควันหยุดสุดสัปดาห์', 'ชุดเที่ยววันหยุด', 'ชุดไปคาเฟ่', 'วันหยุดสบายๆ'],
    date: ['ชุดออกเดท', 'ลุคดินเนอร์สุดโรแมนติก', 'สวยหวานมัดใจ', 'เดทไนท์ลุค'],
    workout: ['ลุคออกกำลังกาย', 'ชุดฟิตเนส', 'สปอร์ตเกิร์ล', 'แฟชั่นชุดกีฬา'],
    any: ['ลุคสุดคอมพลีท', 'แมทช์มาให้แล้ว', 'แฟชั่นนำเทรนด์', 'ลุคนี้ต้องโดน'],
  }

  const options = styleLabels[style] || styleLabels.any
  return randomPick(options) || 'Fashion Ensemble'
}

