    }

    const paletteDesc = paletteDescriptions[colorPalette]
    if (paletteDesc) return paletteDesc
  }

  const styleDescriptions: Record<OutfitStyle, string[]> = {
    business: [
      'เหมาะสำหรับการประชุมสำคัญและการนำเสนองาน',
